render_chart <- function(data, cfg, manifest) { nums <- data[vapply(data, is.numeric, logical(1))]; if (ncol(nums) < 3) stop("平行坐标图至少需要三列数值列"); scaled <- as.data.frame(scale(nums)); scaled$.row <- seq_len(nrow(scaled)); long <- stack(scaled[setdiff(names(scaled), ".row")]); long$row <- rep(seq_len(nrow(scaled)), times = ncol(nums)); long$axis <- factor(long$ind, levels = names(nums)); p <- ggplot2::ggplot(long, ggplot2::aes(x = axis, y = values, group = row)) + ggplot2::geom_line(alpha = 0.5, colour = cfg$color %||% "#0A84FF") + ggplot2::geom_point(size = 1.2, colour = cfg$color %||% "#0A84FF") + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = NULL, y = "标准化数值"); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
